#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    vector<int>leaves;
    for(int i=1;i<=N;i++) if(ch[i].empty()) leaves.push_back(i);

    // Build Halin graph
    vector<set<int>>adj(N+1);
    for(int i=2;i<=N;i++){adj[i].insert(par[i]);adj[par[i]].insert(i);}
    int nL=leaves.size();
    for(int i=0;i<nL;i++){
        int u=leaves[i],v=leaves[(i+1)%nL];
        adj[u].insert(v);adj[v].insert(u);
    }

    // Elimination with min-degree (greedy), using priority queue
    vector<set<int>>eadj(N+1);
    for(int i=1;i<=N;i++) eadj[i]=adj[i];

    vector<bool>elim(N+1,false);
    vector<int>order;
    vector<vector<int>>bags;

    // Use bucket queue for min degree
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>>pq;
    for(int i=1;i<=N;i++) pq.push({(int)eadj[i].size(),i});

    for(int step=0;step<N;step++){
        int v=-1;
        while(!pq.empty()){
            auto[d,u]=pq.top();pq.pop();
            if(!elim[u]&&d==(int)eadj[u].size()){v=u;break;}
        }
        elim[v]=true;
        order.push_back(v);
        vector<int>nb(eadj[v].begin(),eadj[v].end());
        vector<int>bag={v};
        for(int u:nb) bag.push_back(u);
        bags.push_back(bag);
        // Make neighbors clique
        for(int i=0;i<(int)nb.size();i++)
            for(int j=i+1;j<(int)nb.size();j++){
                if(!eadj[nb[i]].count(nb[j])){
                    eadj[nb[i]].insert(nb[j]);
                    eadj[nb[j]].insert(nb[i]);
                }
            }
        for(int u:nb){eadj[u].erase(v);pq.push({(int)eadj[u].size(),u});}
        eadj[v].clear();
    }

    // Build tree: for each bag, parent = bag of earliest-eliminated neighbor
    vector<int>stepOf(N+1);
    for(int i=0;i<N;i++) stepOf[order[i]]=i;

    int K=(int)bags.size();
    vector<int>parBag(K,-1);
    for(int i=0;i<K;i++){
        int mn=N,mi=-1;
        for(int u:bags[i]){
            if(u!=order[i]&&stepOf[u]<mn){mn=stepOf[u];mi=stepOf[u];}
        }
        parBag[i]=mi;
    }

    printf("%d\n",K);
    for(int i=0;i<K;i++){
        printf("%d",(int)bags[i].size());
        for(int v:bags[i]) printf(" %d",v);
        printf("\n");
    }
    for(int i=0;i<K;i++){
        if(parBag[i]!=-1) printf("%d %d\n",i+1,parBag[i]+1);
    }
    return 0;
}
